.hero.hero--editorial .hero-visual > .hero-intro h2{margin:0 0 10px;font-size:clamp(30px,3.6vw,58px);line-height:1.02}
.hero.hero--editorial .hero-visual > .hero-intro p{max-width:none;font-size:clamp(14px,1.25vw,17px);text-wrap:pretty}
